assert(not game:GetService("RunService"):IsRunning(), "Stop testing before installing")
do local p=game:GetService("ServerScriptService"); local s=p:FindFirstChild("Grassland"); if not s then s=Instance.new("Script");s.Name="Grassland";s.Parent=p end;assert(s.ClassName=="Script");s.Source="-- Roblox Luau: ServerScriptService > Grassland.\n-- Six open fenced grass pens. Inventory handles roaming and passive income.\nif workspace:FindFirstChild(\"SlimeMap\") then return end\nlocal map = Instance.new(\"Model\")\nmap.Name = \"SlimeMap\"\nlocal V = Vector3.new\nlocal C = Color3.fromRGB\nlocal palette = {\n    grass = C(102, 180, 72), stone = C(130, 166, 100), trim = C(230, 207, 162),\n    dark = C(78, 100, 53), wood = C(157, 111, 65), path = C(112, 187, 79),\n}\n\n-- One helper handles every anchored building block.\nlocal function part(name, size, position, color, parent, material)\n    local p = Instance.new(\"Part\")\n    p.Name, p.Size, p.Position = name, size, position\n    p.Color = color\n    p.Anchored = true\n    p.Material = material or Enum.Material.SmoothPlastic\n    p.TopSurface, p.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth\n    p.Parent = parent\n    return p\nend\nlocal function model(name, parent)\n    local m = Instance.new(\"Model\")\n    m.Name, m.Parent = name, parent\n    return m\nend\nlocal function sign(text, size, position, color, parent)\n    local board = part(\"Sign\", size, position, color, parent)\n    local gui = Instance.new(\"SurfaceGui\")\n    gui.Face = Enum.NormalId.Back -- Visible while walking north from the plaza.\n    gui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud\n    gui.PixelsPerStud = 35\n    gui.Parent = board\n    local label = Instance.new(\"TextLabel\")\n    label.Size = UDim2.fromScale(1, 1)\n    label.BackgroundTransparency = 1\n    label.Text = text\n    label.TextColor3 = palette.trim\n    label.Font = Enum.Font.GothamBold\n    label.TextScaled = true\n    label.Parent = gui\n    return board\nend\nlocal function cylinder(name, radius, height, position, color, parent)\n    local p = part(name, V(height, radius * 2, radius * 2), position, color, parent)\n    p.Shape = Enum.PartType.Cylinder\n    p.CFrame = CFrame.new(position) * CFrame.Angles(0, 0, math.rad(90))\n    return p\nend\n-- 1. A narrow corridor joins the wider ranch plaza.\n-- Separate floors remove the unused strips outside the tunnel walls.\npart(\"Grassland\", V(102, 2, 610), V(0, -1, -180), palette.grass, map, Enum.Material.Grass)\npart(\"PlazaGround\", V(192, 2, 130), V(0, -1, 190), palette.grass, map, Enum.Material.Grass)\nlocal walls = model(\"BoundaryWalls\", map)\nfor _, x in ipairs({-96, 96}) do\n    part(\"EdgeWall\", V(4, 40, 130), V(x, 20, 190), palette.stone, walls)\n    part(\"WallCap\", V(5, 1, 130), V(x, 40.5, 190), palette.trim, walls)\n    for z = 135, 255, 40 do\n        part(\"Buttress\", V(6, 42, 6), V(x, 21, z), palette.dark, walls)\n    end\nend\n-- Shoulders close the sides where the plaza meets the corridor.\nfor _, x in ipairs({-73, 73}) do\n    part(\"PlazaShoulder\", V(46, 40, 3), V(x, 20, 125), palette.stone, walls)\n    part(\"ShoulderCap\", V(46, 1, 4), V(x, 40.5, 125), palette.trim, walls)\nend\npart(\"NorthEndWall\", V(102, 40, 4), V(0, 20, -485), palette.stone, walls)\npart(\"NorthEndCap\", V(102, 1, 5), V(0, 40.5, -485), palette.trim, walls)\npart(\"SouthEndWall\", V(192, 40, 4), V(0, 20, 255), palette.stone, walls)\npart(\"SouthEndCap\", V(192, 1, 5), V(0, 40.5, 255), palette.trim, walls)\n\n-- 2. An open-air corridor with tall walls and wall-mounted lights.\npart(\"Plaza\", V(172, 0.2, 122), V(0, 0.1, 190), palette.path, map, Enum.Material.Grass)\nlocal tunnel = model(\"NurseryTunnel\", map)\npart(\"MainPath\", V(22, 0.18, 616), V(0, 0.09, -175), palette.path, tunnel, Enum.Material.Grass)\nfor _, x in ipairs({-12, 12}) do\n    part(\"PathEdging\", V(1, 0.24, 616), V(x, 0.12, -175), C(78, 150, 59), tunnel, Enum.Material.Grass)\nend\nfor _, x in ipairs({-49, 49}) do\n    part(\"TunnelWall\", V(3, 40, 604), V(x, 20, -177), palette.stone, tunnel)\n    part(\"WallBase\", V(4, 2, 604), V(x, 1, -177), palette.dark, tunnel)\n    part(\"CorridorWallCap\", V(4, 1, 604), V(x, 40.5, -177), palette.trim, tunnel)\nend\nfor z = -450, 100, 55 do\n    for _, x in ipairs({-47, 47}) do\n        part(\"WallColumn\", V(4, 42, 5), V(x, 21, z), palette.dark, tunnel)\n        part(\"ColumnFoot\", V(6, 2, 7), V(x, 1, z), palette.trim, tunnel)\n    end\n    for _, x in ipairs({-45, 45}) do\n        local lamp = part(\"WallLight\", V(0.5, 3, 2), V(x, 12, z), C(255, 235, 170), tunnel, Enum.Material.Neon)\n        local light = Instance.new(\"PointLight\")\n        light.Color, light.Brightness, light.Range = C(255, 235, 190), 0.65, 28\n        light.Parent = lamp\n    end\nend\n-- Collection replaces the old overhead entrance sign.\nlocal collectZone = model(\"CollectZone\", map)\nlocal pad = part(\"CollectionPad\", V(95, 0.15, 4), V(0, 0.32, 126), C(158, 219, 166), collectZone)\nfor _, z in ipairs({124.125, 127.875}) do\n    part(\"CollectionBorder\", V(95, 0.2, 0.25), V(0, 0.45, z), C(205, 255, 211), collectZone, Enum.Material.Neon)\nend\nfor _, x in ipairs({-47.375, 47.375}) do\n    part(\"CollectionBorder\", V(0.25, 0.2, 4), V(x, 0.45, 126), C(205, 255, 211), collectZone, Enum.Material.Neon)\nend\nlocal floorGui = Instance.new(\"SurfaceGui\")\nfloorGui.Face, floorGui.SizingMode = Enum.NormalId.Top, Enum.SurfaceGuiSizingMode.PixelsPerStud\nfloorGui.PixelsPerStud, floorGui.Parent = 30, pad\nlocal floorLabel = Instance.new(\"TextLabel\")\nfloorLabel.Size = UDim2.fromScale(1, 1)\nfloorLabel.BackgroundTransparency = 1\nfloorLabel.Text, floorLabel.TextColor3 = \"COLLECT ZONE\", C(37, 81, 51)\nfloorLabel.Font, floorLabel.TextScaled = Enum.Font.GothamBold, true\nfloorLabel.Parent = floorGui\n-- An invisible volume detects the player's position, not the carried body's.\nlocal trigger = part(\"CollectionTrigger\", V(95, 12, 4), V(0, 6, 126), C(255, 255, 255), collectZone)\ntrigger.Transparency, trigger.CanCollide, trigger.CanTouch, trigger.CanQuery = 1, false, false, false\nsign(\"STEAL A SLIME\", V(48, 7, 1), V(0, 16, 248), palette.dark, map)\n\n-- 3. Six open grass pens: three on either side of the center lane.\nlocal bases = model(\"Bases\", map)\nlocal fenceColor = C(175, 126, 74)\nlocal railColor = C(202, 157, 99)\nlocal function fenceRail(position, size, parent)\n    for _, height in ipairs({1.4, 3}) do\n        part(\"FenceRail\", size, position + V(0, height, 0), railColor, parent, Enum.Material.Wood)\n    end\nend\nlocal function fencePost(position, parent)\n    part(\"FencePost\", V(1.2, 4.3, 1.2), position + V(0, 2.15, 0), fenceColor, parent, Enum.Material.Wood)\n    part(\"PostCap\", V(1.5, 0.3, 1.5), position + V(0, 4.45, 0), palette.trim, parent, Enum.Material.Wood)\nend\nfor row, z in ipairs({156, 194, 232}) do\n    for sideIndex, side in ipairs({-1, 1}) do\n        local index = (row - 1) * 2 + sideIndex\n        local x = side * 55\n        local base = model(\"Base\" .. index, bases)\n        base:SetAttribute(\"BaseIndex\", index)\n        base:SetAttribute(\"EntrancePosition\", V(side * 22, 0, z))\n        part(\"PenGrass\", V(66, 0.12, 30), V(x, 0.06, z), C(117, 192, 83), base, Enum.Material.Grass)\n        -- Long fences at the north and south edges of each pen.\n        for _, dz in ipairs({-15, 15}) do\n            fenceRail(V(x, 0, z + dz), V(66, 0.45, 0.6), base)\n            for dx = -33, 33, 11 do\n                fencePost(V(x + dx, 0, z + dz), base)\n            end\n        end\n        -- Back fence and two short front sections leave a 12-stud entrance.\n        local backX, frontX = side * 88, side * 22\n        fenceRail(V(backX, 0, z), V(0.6, 0.45, 30), base)\n        fencePost(V(backX, 0, z), base)\n        for _, dz in ipairs({-10.5, 10.5}) do\n            fenceRail(V(frontX, 0, z + dz), V(0.6, 0.45, 9), base)\n        end\n        fencePost(V(frontX, 0, z - 6), base)\n        fencePost(V(frontX, 0, z + 6), base)\n        local board = sign(\"BASE 0\" .. index, V(8, 2.2, 0.5), V(frontX, 4, z - 10.5), palette.wood, base)\n        board.CFrame = CFrame.new(board.Position) * CFrame.Angles(0, -side * math.pi / 2, 0)\n        -- These are reserved spots; placement and income are later features.\n        -- A shared pen replaces individual collection/display pads.\n        base:SetAttribute(\"PenCapacity\", 6)\n\n    end\nend\n\n-- 4. Nursery bays leave the center lane clear.\nlocal nests = model(\"Nests\", map)\nlocal nurseryPositions = {V(-27, 0, 45), V(27, 0, -65), V(-27, 0, -175), V(27, 0, -285), V(-27, 0, -395)}\nlocal nurseryColors = {C(157, 196, 104), C(114, 184, 196), C(172, 150, 207), C(226, 183, 102), C(214, 137, 131)}\nfor index, center in ipairs(nurseryPositions) do\n    local nest = model(\"Nest\" .. index, nests)\n    nest:SetAttribute(\"SpawnCenter\", center + V(0, 0.7, 0))\n    nest:SetAttribute(\"Zone\", index)\n    local accent = nurseryColors[index]\n    sign(\"ZONE 0\" .. index, V(22, 3, 0.6), V(-35, 12, center.Z + 35), palette.dark, tunnel)\n    part(\"ZoneSignPost\", V(1, 12, 1), V(-35, 6, center.Z + 35), accent, tunnel)\n    cylinder(\"StonePlinth\", 15, 0.5, center + V(0, 0.25, 0), palette.trim, nest)\n    cylinder(\"SoftBed\", 12, 0.2, center + V(0, 0.6, 0), accent, nest)\n    for segment = 0, 31 do\n        local angle = segment * math.pi * 2 / 32\n        local position = center + V(math.cos(angle) * 13, 0.9, math.sin(angle) * 13)\n        local rim = part(\"NestRim\", V(2.8, 0.8, 2.8), position, palette.wood, nest)\n        rim.CFrame = CFrame.new(position) * CFrame.Angles(0, -angle, 0)\n    end\n    for _, dx in ipairs({-11, 11}) do\n        part(\"CanopyPost\", V(1, 9, 1), center + V(dx, 4.5, -9), palette.wood, nest)\n    end\n    part(\"Canopy\", V(28, 1, 8), center + V(0, 9, -10), accent, nest)\n    sign(\"NURSERY 0\" .. index, V(22, 2.5, 0.5), center + V(0, 7, -8), palette.dark, nest)\n    -- A short side path connects each bay to the main walkway.\n    part(\"NurseryApproach\", V(12, 0.15, 7), V(center.X / 2, 0.075, center.Z), palette.path, tunnel, Enum.Material.Grass)\nend\n\n-- The existing spawn is reused so a second spawn is never created.\nlocal spawn = workspace:FindFirstChildWhichIsA(\"SpawnLocation\")\nif spawn then\n    spawn.CFrame = CFrame.new(0, 0.6, 229)\n    spawn.Size = V(10, 1, 10)\n    spawn.Transparency = 1\n    spawn.CanCollide = false\n    spawn.Neutral = true\n    for _, decoration in ipairs(spawn:GetChildren()) do\n        if decoration:IsA(\"Decal\") or decoration:IsA(\"Texture\") then\n            decoration.Transparency = 1\n        end\n    end\nend\nmap:SetAttribute(\"MapVersion\", \"SixGrassPens\")\nmap.Parent = workspace\n" end
do local p=game:GetService("ServerScriptService"); local s=p:FindFirstChild("Slimes"); if not s then s=Instance.new("Script");s.Name="Slimes";s.Parent=p end;assert(s.ClassName=="Script");s.Source="-- Put this Script in ServerScriptService alongside Grassland.\n-- Piece 1: one table stores the appearance and fixed rarity of each type.\nlocal types = {\n    {name = \"Grass\", rarity = \"Common\", color = Color3.fromRGB(110, 210, 80)},\n    {name = \"Mud\", rarity = \"Common\", color = Color3.fromRGB(135, 90, 60)},\n    {name = \"Water\", rarity = \"Uncommon\", color = Color3.fromRGB(70, 175, 245)},\n    {name = \"Honey\", rarity = \"Rare\", color = Color3.fromRGB(245, 160, 40)},\n    {name = \"Crystal\", rarity = \"Epic\", color = Color3.fromRGB(175, 115, 245)},\n    {name = \"Gold\", rarity = \"Legendary\", color = Color3.fromRGB(255, 215, 65)},\n}\n\n-- Piece 2: a helper creates one anchored, rounded part.\nlocal function ball(name, size, position, color, parent)\n    local part = Instance.new(\"Part\")\n    part.Name = name\n    part.Shape = Enum.PartType.Ball\n    part.Size = size\n    part.Position = position\n    part.Color = color\n    part.Material = Enum.Material.SmoothPlastic\n    part.Anchored = true\n    part.CanCollide = false\n    part.TopSurface = Enum.SurfaceType.Smooth\n    part.BottomSurface = Enum.SurfaceType.Smooth\n    part.Parent = parent\n    return part\nend\n\n-- Piece 3: wait until Grassland has finished creating the nests.\nlocal map = workspace:WaitForChild(\"SlimeMap\")\nlocal nests = map:WaitForChild(\"Nests\")\nif map:FindFirstChild(\"WildSlimes\") then return end\nlocal slimes = Instance.new(\"Folder\")\nslimes.Name = \"WildSlimes\"\nslimes.Parent = map\n\nfor index, slimeType in ipairs(types) do\n    -- Two types per nest: indices 1/2, 3/4, and 5/6.\n    local nestIndex = math.ceil(index / 2)\n    local nest = nests:WaitForChild(\"Nest\" .. nestIndex)\n    local center = nest:GetAttribute(\"SpawnCenter\") or nest:GetBoundingBox().Position\n    local side = index % 2 == 1 and -4 or 4\n    local position = Vector3.new(center.X + side, center.Y, center.Z)\n\n    local slime = Instance.new(\"Model\")\n    slime.Name = slimeType.name .. \"Slime\"\n    slime:SetAttribute(\"SlimeType\", slimeType.name)\n    slime:SetAttribute(\"Rarity\", slimeType.rarity)\n    slime:SetAttribute(\"NestIndex\", nestIndex)\n    slime.Parent = slimes\n\n    -- The bottom is hidden beneath the ground for a flat-bottomed dome.\n    local body = ball(\"Body\", Vector3.new(4, 3, 4), position + Vector3.new(0, 0.45, 0), slimeType.color, slime)\n    body.Transparency = 0.08\n    slime.PrimaryPart = body\n    local black = Color3.fromRGB(20, 20, 25)\n    ball(\"LeftEye\", Vector3.new(0.28, 0.4, 0.22), position + Vector3.new(-0.65, 1, 1.77), black, slime)\n    ball(\"RightEye\", Vector3.new(0.28, 0.4, 0.22), position + Vector3.new(0.65, 1, 1.77), black, slime)\n    ball(\"Mouth\", Vector3.new(0.4, 0.18, 0.18), position + Vector3.new(0, 0.65, 1.98), black, slime)\nend\nprint(\"Slimes ready: Grass, Mud, Water, Honey, Crystal, Gold\")\n" end
do local p=game:GetService("ServerScriptService"); local s=p:FindFirstChild("Capture"); if not s then s=Instance.new("Script");s.Name="Capture";s.Parent=p end;assert(s.ClassName=="Script");s.Source="-- Roblox Luau: ServerScriptService > Capture.\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal StarterPack = game:GetService(\"StarterPack\")\nlocal ServerStorage = game:GetService(\"ServerStorage\")\nlocal CombatRules = require(script.Parent:WaitForChild(\"CombatRules\"))\nlocal UpgradeRules = require(script.Parent:WaitForChild(\"UpgradeRules\"))\nlocal secured = Instance.new(\"Folder\")\nsecured.Name, secured.Parent = \"SecuredSlimes\", ServerStorage\nlocal collectionTrigger\nlocal HOLD_SECONDS, REACH = 2, 10\nlocal random = Random.new()\nlocal states, attempts, carrying, messageVersions = {}, {}, {}, {}\nlocal function movement(player)\n    local character = player.Character\n    local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n    if not humanoid or humanoid.Health <= 0 then return end\n    local record = carrying[player]\n    local speedLevel, grabberLevel = player:GetAttribute(\"SpeedLevel\") or 0, player:GetAttribute(\"GrabberLevel\") or 0\n    if CombatRules.IsStunned(player) then\n        humanoid.WalkSpeed = 0\n    elseif record then\n        humanoid.WalkSpeed = UpgradeRules.CarrySpeed(speedLevel, grabberLevel, record.state.weight, player:GetAttribute(\"GrabberPower\") or 10)\n    else\n        humanoid.WalkSpeed = UpgradeRules.Speed(speedLevel)\n    end\nend\nlocal refreshMovement = Instance.new(\"BindableFunction\")\nrefreshMovement.Name, refreshMovement.OnInvoke = \"RefreshMovement\", movement\nrefreshMovement.Parent = script\n\n-- PIECE 1: build the grabber and give each player clear instructions.\nlocal function piece(name, size, color, parent)\n    local p = Instance.new(\"Part\")\n    p.Name, p.Size, p.Color = name, size, color\n    p.Material = Enum.Material.SmoothPlastic\n    p.CanCollide, p.Massless = false, true\n    p.Parent = parent\n    return p\nend\nlocal tool = Instance.new(\"Tool\")\ntool.Name, tool.CanBeDropped = \"Slime Grabber\", false\nlocal handle = piece(\"Handle\", Vector3.new(1, 1, 2), Color3.fromRGB(65, 106, 94), tool)\nlocal nozzle = piece(\"Nozzle\", Vector3.new(1.4, 1.4, 0.6), Color3.fromRGB(190, 240, 205), tool)\nnozzle.CFrame = handle.CFrame * CFrame.new(0, 0, -1.2)\nlocal joint = Instance.new(\"WeldConstraint\")\njoint.Part0, joint.Part1, joint.Parent = handle, nozzle, handle\nlocal tip = Instance.new(\"Attachment\")\ntip.Name, tip.Position, tip.Parent = \"TetherTip\", Vector3.new(0, 0, -1.6), handle\ntool.Parent = StarterPack\n\nlocal function hint(player, text)\n    local gui = player:FindFirstChild(\"PlayerGui\")\n    gui = gui and gui:FindFirstChild(\"CaptureHint\")\n    if gui then gui.Message.Text = text end\nend\nlocal function defaultHint(player)\n    if carrying[player] then\n        if player:GetAttribute(\"ChasedBy\") then\n            return \"GIANT PARENT CHASING! Reach the green COLLECT ZONE!  |  Q: drop baby\"\n        end\n        return \"Carry this baby to the green COLLECT ZONE to secure it.  |  Q: drop baby\"\n    end\n    return \"Collected: \" .. (player:GetAttribute(\"CollectedSlimes\") or 0) .. \"  |  Equip Slime Grabber [1] and hold E near a baby\"\nend\nlocal function message(player, text)\n    local version = (messageVersions[player] or 0) + 1\n    messageVersions[player] = version\n    hint(player, text)\n    task.delay(4, function()\n        if player.Parent and messageVersions[player] == version then\n            hint(player, defaultHint(player))\n        end\n    end)\nend\nlocal function setupCharacter(player, character)\n    local backpack = player:WaitForChild(\"Backpack\")\n    if not backpack:FindFirstChild(tool.Name) and not character:FindFirstChild(tool.Name) then\n        tool:Clone().Parent = backpack\n    end\n    local playerGui = player:WaitForChild(\"PlayerGui\")\n    if not playerGui:FindFirstChild(\"CaptureHint\") then\n        local gui = Instance.new(\"ScreenGui\")\n        gui.Name, gui.ResetOnSpawn = \"CaptureHint\", false\n        local label = Instance.new(\"TextLabel\")\n        label.Name = \"Message\"\n        label.AnchorPoint = Vector2.new(0.5, 1)\n        label.Position, label.Size = UDim2.new(0.5, 0, 1, -85), UDim2.new(0.8, 0, 0, 54)\n        label.BackgroundColor3 = Color3.fromRGB(35, 55, 46)\n        label.BackgroundTransparency = 0.15\n        label.TextColor3 = Color3.fromRGB(245, 240, 220)\n        label.Font, label.TextSize, label.TextWrapped = Enum.Font.GothamMedium, 17, true\n        label.Parent, gui.Parent = gui, playerGui\n    end\n    hint(player, defaultHint(player))\n    character:WaitForChild(\"Humanoid\")\n    movement(player)\nend\n\n-- PIECE 2: the server checks equipment, range, timing, power, and ownership.\n-- Weights live only in this server table, never as visible model attributes.\nlocal function power(player)\n    local value = player:GetAttribute(\"GrabberPower\")\n    if type(value) ~= \"number\" or value ~= value then return 10 end\n    return math.clamp(value, 0, 1000000)\nend\nlocal function eligible(player, state)\n    local character = player.Character\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n    local equipped = character and character:FindFirstChild(\"Slime Grabber\")\n    if not root or not humanoid or humanoid.Health <= 0 then return false end\n    if not equipped or not equipped:IsA(\"Tool\") then return false end\n    if CombatRules.IsStunned(player) then return false end\n    if carrying[player] or state.slime:GetAttribute(\"Captured\") then return false end\n    if state.owner and state.owner ~= player then return false end\n    if not state.slime.PrimaryPart or not state.slime:IsDescendantOf(workspace) then return false end\n    if (root.Position - state.slime.PrimaryPart.Position).Magnitude > REACH then return false end\n    local params = RaycastParams.new()\n    params.FilterType = Enum.RaycastFilterType.Exclude\n    -- Avatars and cosmetic accessories must not block collecting a nearby baby.\n    local exclusions = {state.slime}\n    for _, other in ipairs(Players:GetPlayers()) do\n        if other.Character then table.insert(exclusions, other.Character) end\n    end\n    params.FilterDescendantsInstances = exclusions\n    local origin = root.Position + Vector3.new(0, 1, 0)\n    if workspace:Raycast(origin, state.slime.PrimaryPart.Position - origin, params) then return false end\n    return true, root, humanoid, equipped\nend\nlocal function cancel(player)\n    local state = attempts[player]\n    if not state then return end\n    attempts[player] = nil\n    state.owner, state.started, state.released = nil, nil, nil\n    if state.beam then state.beam:Destroy(); state.beam = nil end\nend\nlocal function begin(player, state)\n    if not eligible(player, state) then\n        message(player, \"Equip your grabber, move closer, and carry only one baby at a time.\")\n        return\n    end\n    cancel(player)\n    state.weight = state.weight or random:NextInteger(1, 20)\n    if state.weight > power(player) then\n        message(player, \"This baby needs more Grabber Power. Try another slime.\")\n        return\n    end\n    local _, _, _, equipped = eligible(player, state)\n    state.owner, state.started, state.released = player, os.clock(), nil\n    state.holdSeconds = UpgradeRules.HoldSeconds(player:GetAttribute(\"GrabberLevel\") or 0)\n    attempts[player] = state\n    local beam = Instance.new(\"Beam\")\n    beam.Attachment0 = equipped.Handle.TetherTip\n    beam.Attachment1 = state.attachment\n    beam.Width0, beam.Width1, beam.FaceCamera = 0.15, 0.1, true\n    beam.Color = ColorSequence.new(Color3.fromRGB(190, 245, 205))\n    beam.Parent, state.beam = state.slime.PrimaryPart, beam\n    message(player, \"Keep holding E to pull this baby free...\")\nend\n\n-- PIECE 3: weld a successful capture to the character and apply slowdown.\n-- Future chase code can listen to this server-only event.\nlocal captured = Instance.new(\"BindableEvent\")\ncaptured.Name, captured.Parent = \"SlimeCaptured\", script\nlocal released = Instance.new(\"BindableEvent\")\nreleased.Name, released.Parent = \"SlimeReleased\", script\nlocal function release(player, dropFrame)\n    cancel(player)\n    local record = carrying[player]\n    if not record then return end\n    carrying[player] = nil\n    for _, weld in ipairs(record.welds) do weld:Destroy() end\n    for _, p in ipairs(record.state.slime:GetDescendants()) do\n        if p:IsA(\"BasePart\") then p.Anchored = true end\n    end\n    local state = record.state\n    state.dropVersion = (state.dropVersion or 0) + 1\n    state.dropped = dropFrame ~= nil\n    state.dropExpires = state.dropped and (os.clock() + CombatRules.DropLifetime) or nil\n    state.prompt.HoldDuration = state.dropped and 0 or HOLD_SECONDS\n    state.prompt.ActionText = state.dropped and \"Pick up dropped baby\" or \"Pull with grabber\"\n    record.state.slime:PivotTo(dropFrame or record.state.home)\n    record.state.slime:SetAttribute(\"Captured\", false)\n    record.state.slime:SetAttribute(\"CarrierUserId\", nil)\n    record.state.prompt.Enabled = true\n    if record.humanoid.Parent then record.humanoid.WalkSpeed = UpgradeRules.Speed(player:GetAttribute(\"SpeedLevel\") or 0) end\n    player:SetAttribute(\"CarryingSlime\", nil)\n    released:Fire(player, record.state.slime)\nend\nlocal caught = Instance.new(\"BindableEvent\")\ncaught.Name, caught.Parent = \"ParentCaught\", script\ncaught.Event:Connect(function(player, slime)\n    local record = carrying[player]\n    if record and record.state.slime == slime then\n        release(player)\n        message(player, \"The parent caught you! The baby returned to its nursery.\")\n    end\nend)\nlocal function finish(player, state)\n    if state.dropped then\n        if state.dropExpires and os.clock() >= state.dropExpires then return end\n    else\n        if attempts[player] ~= state or state.owner ~= player then return end\n        local elapsed = (state.released or os.clock()) - state.started\n        if elapsed < state.holdSeconds - 0.08 then cancel(player); return end\n    end\n    local valid, root, humanoid = eligible(player, state)\n\n    if not valid or state.weight > power(player) then cancel(player); return end\n    cancel(player)\n    local slime, body = state.slime, state.slime.PrimaryPart\n    state.dropped, state.dropExpires = false, nil\n    state.dropVersion = (state.dropVersion or 0) + 1\n    state.prompt.HoldDuration, state.prompt.ActionText = HOLD_SECONDS, \"Pull with grabber\"\n    state.prompt.Enabled = false\n    slime:SetAttribute(\"Captured\", true)\n    slime:SetAttribute(\"CarrierUserId\", player.UserId)\n    player:SetAttribute(\"CarryingSlime\", slime.Name)\n    slime:PivotTo(root.CFrame * CFrame.new(2.5, 1, -3))\n    local welds = {}\n    for _, p in ipairs(slime:GetDescendants()) do\n        if p:IsA(\"BasePart\") then\n            p.Anchored, p.CanCollide, p.Massless = false, false, true\n            if p ~= body then\n                local weld = Instance.new(\"WeldConstraint\")\n                weld.Part0, weld.Part1, weld.Parent = body, p, body\n                table.insert(welds, weld)\n            end\n        end\n    end\n    local grip = Instance.new(\"WeldConstraint\")\n    grip.Part0, grip.Part1, grip.Parent = root, body, body\n    table.insert(welds, grip)\n    local speed = humanoid.WalkSpeed\n    carrying[player] = {state = state, humanoid = humanoid, speed = speed, welds = welds}\n    movement(player)\n    message(player, \"Captured \" .. slime:GetAttribute(\"SlimeType\") .. \"! Run to the COLLECT ZONE before its parent catches you.\")\n    captured:Fire(player, slime, state.weight)\nend\n\n-- Collection stores secured babies privately for this session.\n-- The later inventory feature can read these models and their hidden weights.\nlocal slimeSecured = Instance.new(\"BindableEvent\")\nslimeSecured.Name, slimeSecured.Parent = \"SlimeSecured\", script\nlocal function collect(player, record)\n    local character = player.Character\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    if not root or record.humanoid.Health <= 0 or not collectionTrigger then return end\n    local position = collectionTrigger.CFrame:PointToObjectSpace(root.Position)\n    local half = collectionTrigger.Size / 2\n    if math.abs(position.X) > half.X or math.abs(position.Y) > half.Y or math.abs(position.Z) > half.Z then return end\n    local folder = secured:FindFirstChild(tostring(player.UserId))\n    if not folder then return end\n    -- Clear carrying first, so repeated frames cannot award the same baby twice.\n    carrying[player] = nil\n    for _, weld in ipairs(record.welds) do weld:Destroy() end\n    local slime = record.state.slime\n    for _, item in ipairs(slime:GetDescendants()) do\n        if item:IsA(\"BasePart\") then item.Anchored = true end\n    end\n    slime.Parent = folder -- ServerStorage does not replicate to players.\n    slime:SetAttribute(\"Weight\", record.state.weight)\n    slime:SetAttribute(\"Secured\", true)\n    slime:SetAttribute(\"CarrierUserId\", nil)\n    record.humanoid.WalkSpeed = UpgradeRules.Speed(player:GetAttribute(\"SpeedLevel\") or 0)\n    player:SetAttribute(\"CarryingSlime\", nil)\n    player:SetAttribute(\"CollectedSlimes\", #folder:GetChildren())\n    states[slime] = nil\n    message(player, \"Secured \" .. slime:GetAttribute(\"SlimeType\") .. \" baby! Collected: \" .. #folder:GetChildren())\n    slimeSecured:Fire(player, slime, record.state.weight)\nend\n\nlocal function setupPlayer(player)\n    local folder = Instance.new(\"Folder\")\n    folder.Name, folder.Parent = tostring(player.UserId), secured\n    player:SetAttribute(\"CollectedSlimes\", 0)\n    if player:GetAttribute(\"GrabberPower\") == nil then player:SetAttribute(\"GrabberPower\", 10) end\n    for _, attribute in ipairs({\"SpeedLevel\", \"GrabberLevel\", \"GrabberPower\"}) do\n        player:GetAttributeChangedSignal(attribute):Connect(function() movement(player) end)\n    end\n    player.CharacterRemoving:Connect(function() release(player) end)\n    player.CharacterAdded:Connect(function(character)\n        setupCharacter(player, character)\n        local humanoid = character:WaitForChild(\"Humanoid\")\n        humanoid.Died:Connect(function() release(player) end)\n    end)\n    if player.Character then\n        local character = player.Character\n        task.spawn(function()\n            setupCharacter(player, character)\n            character:WaitForChild(\"Humanoid\").Died:Connect(function() release(player) end)\n        end)\n    end\nend\nPlayers.PlayerAdded:Connect(setupPlayer)\nPlayers.PlayerRemoving:Connect(function(player)\n    release(player)\n    messageVersions[player] = nil\n    local folder = secured:FindFirstChild(tostring(player.UserId))\n    if folder then folder:Destroy() end\nend)\nfor _, player in ipairs(Players:GetPlayers()) do setupPlayer(player) end\n\nRunService.Heartbeat:Connect(function()\n    for player, state in pairs(attempts) do\n        if not eligible(player, state) or (state.released and os.clock() - state.released > 0.2) then\n            cancel(player)\n        end\n    end\n    for player, record in pairs(carrying) do collect(player, record) end\n    local now = os.clock()\n    for _, state in pairs(states) do\n        if state.dropped and state.dropExpires and now >= state.dropExpires then\n            cancel(state.owner)\n            state.dropped, state.dropExpires = false, nil\n            state.prompt.Enabled = true\n            state.prompt.HoldDuration, state.prompt.ActionText = HOLD_SECONDS, \"Pull with grabber\"\n            state.slime:PivotTo(state.home)\n        end\n    end\nend)\nlocal slimes = workspace:WaitForChild(\"SlimeMap\"):WaitForChild(\"WildSlimes\")\ncollectionTrigger = slimes.Parent:WaitForChild(\"CollectZone\"):WaitForChild(\"CollectionTrigger\")\nlocal function register(slime)\n    if not slime:IsA(\"Model\") or states[slime] then return end\n    slime:WaitForChild(\"Mouth\") -- The spawner creates the mouth last.\n    local body = slime.PrimaryPart\n    if not body then return end\n    local attachment = Instance.new(\"Attachment\")\n    attachment.Parent = body\n    local prompt = Instance.new(\"ProximityPrompt\")\n    prompt.Name, prompt.ObjectText, prompt.ActionText = \"CapturePrompt\", slime:GetAttribute(\"SlimeType\") .. \" baby\", \"Pull with grabber\"\n    prompt.HoldDuration, prompt.MaxActivationDistance = HOLD_SECONDS, REACH\n    prompt.RequiresLineOfSight = false -- The server checks the actual path.\n    prompt.Parent = body\n    local state = {slime = slime, prompt = prompt, attachment = attachment, home = slime:GetPivot()}\n    states[slime] = state\n    prompt.PromptButtonHoldBegan:Connect(function(player)\n        if not state.dropped then begin(player, state) end\n    end)\n    prompt.PromptButtonHoldEnded:Connect(function(player)\n        if attempts[player] == state then state.released = os.clock() end\n    end)\n    prompt.Triggered:Connect(function(player) finish(player, state) end)\nend\nslimes.ChildAdded:Connect(function(slime) task.spawn(register, slime) end)\nfor _, slime in ipairs(slimes:GetChildren()) do task.spawn(register, slime) end\nprint(\"Capture ready: equip Slime Grabber, then hold E near a baby.\")\n\n\n-- Only server scripts can invoke this function. It atomically releases capture ownership.\nlocal interrupt = Instance.new(\"BindableFunction\")\ninterrupt.Name = \"InterruptForBat\"\ninterrupt.OnInvoke = function(player)\n    cancel(player)\n    local record = carrying[player]\n    if not record then return false end\n    local character = player.Character\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    if not root then release(player); return false end\n    local position = Vector3.new(math.clamp(root.Position.X, -38, 38), root.Position.Y, math.min(root.Position.Z, CombatRules.SafeZ - 4))\n    local params = RaycastParams.new()\n    params.FilterType = Enum.RaycastFilterType.Exclude\n    local exclusions = {record.state.slime}\n    for _, other in ipairs(Players:GetPlayers()) do\n        if other.Character then table.insert(exclusions, other.Character) end\n    end\n    local map = workspace:FindFirstChild(\"SlimeMap\")\n    if map then\n        if map:FindFirstChild(\"WildSlimes\") then table.insert(exclusions, map.WildSlimes) end\n        if map:FindFirstChild(\"Guardians\") then table.insert(exclusions, map.Guardians) end\n    end\n    params.FilterDescendantsInstances = exclusions\n    local ground = workspace:Raycast(position + Vector3.new(0, 4, 0), Vector3.new(0, -100, 0), params)\n    local dropFrame\n    if ground then\n        local height = record.state.slime.PrimaryPart.Size.Y * 0.5 + 0.1\n        dropFrame = CFrame.new(ground.Position + Vector3.new(0, height, 0)) * record.state.home.Rotation\n    end\n    release(player, dropFrame)\n    message(player, dropFrame and \"You dropped your baby! Equip your grabber and pick it back up.\" or \"Your baby returned to its nursery.\")\n    return dropFrame ~= nil\nend\ninterrupt.Parent = script\n" end
do local p=game:GetService("ServerScriptService"); local s=p:FindFirstChild("Guardians"); if not s then s=Instance.new("Script");s.Name="Guardians";s.Parent=p end;assert(s.ClassName=="Script");s.Source="-- Roblox Luau: ServerScriptService > Guardians.\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal PathfindingService = game:GetService(\"PathfindingService\")\nlocal capture = script.Parent:WaitForChild(\"Capture\")\nlocal captured = capture:WaitForChild(\"SlimeCaptured\")\nlocal secured = capture:WaitForChild(\"SlimeSecured\")\nlocal released = capture:WaitForChild(\"SlimeReleased\")\nlocal caught = capture:WaitForChild(\"ParentCaught\")\nlocal map = workspace:WaitForChild(\"SlimeMap\")\nlocal slimes = map:WaitForChild(\"WildSlimes\")\nlocal trigger = map:WaitForChild(\"CollectZone\"):WaitForChild(\"CollectionTrigger\")\nlocal safeZ = trigger.Position.Z - trigger.Size.Z / 2\nlocal SPEED, GRACE, CATCH_DISTANCE = 14, 1.5, 6\nlocal V = Vector3.new\nlocal records = {}\nlocal parents = Instance.new(\"Folder\")\nparents.Name, parents.Parent = \"Guardians\", map\n\n-- PIECE 1: build a large parent with the baby's color and angry eyebrows.\nlocal function part(name, size, color, frame, parent, ball)\n    local p = Instance.new(\"Part\")\n    p.Name, p.Size, p.Color, p.CFrame = name, size, color, frame\n    p.Anchored, p.CanCollide, p.CanTouch, p.CanQuery = true, false, false, false\n    p.Material = Enum.Material.SmoothPlastic\n    if ball then p.Shape = Enum.PartType.Ball end\n    p.Parent = parent\n    return p\nend\nlocal function register(slime)\n    if records[slime] then return records[slime] end\n    if not slime:IsA(\"Model\") then return end\n    slime:WaitForChild(\"Mouth\")\n    local body = slime.PrimaryPart\n    if not body then return end\n    local nest = map.Nests:FindFirstChild(\"Nest\" .. tostring(slime:GetAttribute(\"NestIndex\")))\n    if not nest then return end\n    local center = nest:GetAttribute(\"SpawnCenter\")\n    local side = body.Position.X < center.X and -1 or 1\n    local home = V(center.X + side * 9, 0, center.Z - 24)\n    local model = Instance.new(\"Model\")\n    model.Name = slime:GetAttribute(\"SlimeType\") .. \"Parent\"\n    model:SetAttribute(\"SlimeType\", slime:GetAttribute(\"SlimeType\"))\n    model:SetAttribute(\"State\", \"Idle\")\n    local root = part(\"Root\", V(1, 1, 1), body.Color, CFrame.new(home), model)\n    root.Transparency = 1\n    model.PrimaryPart = root\n    local skin = part(\"Body\", V(14, 12, 14), body.Color, CFrame.new(home + V(0, 4.2, 0)), model, true)\n    skin.Transparency = 0.06\n    local black = Color3.fromRGB(25, 30, 24)\n    for _, x in ipairs({-2.3, 2.3}) do\n        part(\"Eye\", V(0.9, 1.2, 0.45), black, CFrame.new(home + V(x, 5.5, -6.3)), model, true)\n        part(\"AngryBrow\", V(2.5, 0.5, 0.45), black,\n            CFrame.new(home + V(x, 6.5, -6)) * CFrame.Angles(0, 0, math.rad(x < 0 and -25 or 25)), model)\n    end\n    part(\"Mouth\", V(2.3, 0.55, 0.4), black, CFrame.new(home + V(0, 3.6, -6.9)), model, true)\n    model.Parent = parents\n    local record = {\n        slime = slime, model = model, home = home, position = home,\n        rotation = CFrame.Angles(0, math.pi, 0), phase = 0,\n        revision = 0, nextPath = 0, waypoints = {}, waypoint = 1,\n    }\n    records[slime] = record\n    model:PivotTo(CFrame.new(home) * record.rotation)\n    return record\nend\n\n-- PIECE 2: capture starts a chase; collection, release, or leaving ends it.\nlocal function stop(record)\n    local player = record.target\n    if player and player:GetAttribute(\"ChasedBy\") == record.model.Name then\n        player:SetAttribute(\"ChasedBy\", nil)\n    end\n    record.target, record.character = nil, nil\n    record.revision = record.revision + 1\n    record.waypoints, record.waypoint, record.nextPath = {}, 1, 0\n    record.model:SetAttribute(\"State\", \"Returning\")\n    record.model:SetAttribute(\"TargetUserId\", nil)\nend\ncaptured.Event:Connect(function(player, slime)\n    local record = records[slime] or register(slime)\n    if not record then return end\n    if record.target then stop(record) end\n    record.target, record.character = player, player.Character\n    record.wakeAt = os.clock() + GRACE\n    record.revision = record.revision + 1\n    record.waypoints, record.waypoint, record.nextPath = {}, 1, 0\n    record.model:SetAttribute(\"State\", \"Chasing\")\n    record.model:SetAttribute(\"TargetUserId\", player.UserId)\n    player:SetAttribute(\"ChasedBy\", record.model.Name)\nend)\nlocal function endChase(_, slime)\n    local record = records[slime]\n    if record then stop(record) end\nend\nsecured.Event:Connect(endChase)\nreleased.Event:Connect(endChase)\nPlayers.PlayerRemoving:Connect(function(player)\n    for _, record in pairs(records) do\n        if record.target == player then stop(record) end\n    end\nend)\n\n-- PIECE 3: request paths without blocking the frame update.\n-- A revision number prevents an old path from replacing a newer chase.\nlocal obstacles = RaycastParams.new()\nobstacles.FilterType = Enum.RaycastFilterType.Include\nobstacles.FilterDescendantsInstances = {map.NurseryTunnel, map.Nests, map.BoundaryWalls}\nlocal function clearStep(position, delta)\n    for _, height in ipairs({3, 9}) do\n        if workspace:Raycast(position + V(0, height, 0), delta, obstacles) then return false end\n    end\n    return true\nend\nlocal function requestPath(record, goal, now)\n    if record.pathBusy or now < record.nextPath then return end\n    record.pathBusy, record.nextPath = true, now + 1\n    local revision, start = record.revision, record.position\n    task.spawn(function()\n        local path = PathfindingService:CreatePath({AgentRadius = 7, AgentHeight = 11, AgentCanJump = false, WaypointSpacing = 5})\n        local ok = pcall(function() path:ComputeAsync(start + V(0, 2, 0), goal + V(0, 2, 0)) end)\n        record.pathBusy = false\n        if record.revision ~= revision then return end\n        if ok and path.Status == Enum.PathStatus.Success then\n            local waypoints = path:GetWaypoints()\n            local leavesCorridor = false\n            for _, waypoint in ipairs(waypoints) do\n                if math.abs(waypoint.Position.X) > 40 or waypoint.Position.Z > safeZ - 7 then\n                    leavesCorridor = true\n                    break\n                end\n            end\n            -- The wide center lane gives large parents room around nursery roofs.\n            if leavesCorridor then\n                record.waypoints, record.waypoint = {{Position = V(0, 0, start.Z)}}, 1\n            else\n                record.waypoints, record.waypoint = waypoints, 2\n            end\n        else\n            record.waypoints, record.waypoint = {}, 1\n        end\n    end)\nend\nlocal function tick(record, dt, now)\n    local goal\n    if record.target then\n        local player, character = record.target, record.character\n        local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n        local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n        if not player.Parent or player.Character ~= character or not root or not humanoid or humanoid.Health <= 0\n            or player:GetAttribute(\"CarryingSlime\") ~= record.slime.Name or root.Position.Z >= safeZ then\n            stop(record)\n        elseif now >= record.wakeAt then\n            local delta = root.Position - record.position\n            local horizontal = V(delta.X, 0, delta.Z)\n            if horizontal.Magnitude <= CATCH_DISTANCE and math.abs(delta.Y) < 12 then\n                -- Check the line of sight before catching through an obstacle.\n                local params = RaycastParams.new()\n                params.FilterType = Enum.RaycastFilterType.Exclude\n                params.FilterDescendantsInstances = {character, parents, record.slime}\n                if not workspace:Raycast(record.position + V(0, 4, 0), root.Position - (record.position + V(0, 4, 0)), params) then\n                    caught:Fire(player, record.slime)\n                    stop(record)\n                else\n                    goal = V(math.clamp(root.Position.X, -39, 39), 0, math.min(root.Position.Z, safeZ - 7))\n                end\n            else\n                goal = V(math.clamp(root.Position.X, -39, 39), 0, math.min(root.Position.Z, safeZ - 7))\n            end\n        end\n    end\n    if not record.target and record.model:GetAttribute(\"State\") == \"Returning\" then\n        if (record.position - record.home).Magnitude < 1.1 then\n            record.position = record.home\n            record.model:SetAttribute(\"State\", \"Idle\")\n        else\n            goal = record.home\n        end\n    end\n    local moved = false\n    if goal then\n        requestPath(record, goal, now)\n        local waypoint = record.waypoints[record.waypoint]\n        local destination = waypoint and V(waypoint.Position.X, 0, waypoint.Position.Z) or goal\n        local delta = destination - record.position\n        if delta.Magnitude < 1 then\n            record.waypoint = record.waypoint + 1\n        else\n            local step = delta.Unit * math.min(delta.Magnitude, SPEED * math.min(dt, 0.1))\n            local nextPosition = record.position + step\n            if nextPosition.Z <= safeZ - 7 and math.abs(nextPosition.X) <= 40 and clearStep(record.position, step) then\n                record.position = nextPosition\n                record.rotation = record.rotation:Lerp(CFrame.lookAt(V(0, 0, 0), delta.Unit), math.min(1, dt * 8))\n                moved = true\n            else\n                record.nextPath = 0\n            end\n        end\n    end\n    record.phase = record.phase + dt * (moved and 8 or 2)\n    local bounce = math.abs(math.sin(record.phase)) * (moved and 0.7 or 0.08)\n    record.model:PivotTo(CFrame.new(record.position + V(0, bounce, 0)) * record.rotation)\nend\nslimes.ChildAdded:Connect(function(slime) task.spawn(register, slime) end)\nfor _, slime in ipairs(slimes:GetChildren()) do task.spawn(register, slime) end\nRunService.Heartbeat:Connect(function(dt)\n    local now = os.clock()\n    for _, record in pairs(records) do tick(record, dt, now) end\nend)\nprint(\"Guardians ready: giant parents chase captured babies and stop at the collect zone.\")\n" end
do local p=game:GetService("ServerScriptService"); local s=p:FindFirstChild("Bat"); if not s then s=Instance.new("Script");s.Name="Bat";s.Parent=p end;assert(s.ClassName=="Script");s.Source="-- Slime Bat: clients request swings; the server decides range, safety and the hit.\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal StarterPack = game:GetService(\"StarterPack\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal Debris = game:GetService(\"Debris\")\nlocal Rules = require(script.Parent:WaitForChild(\"CombatRules\"))\nlocal capture = script.Parent:WaitForChild(\"Capture\")\nlocal interrupt = capture:WaitForChild(\"InterruptForBat\")\nlocal refreshMovement = capture:WaitForChild(\"RefreshMovement\")\nlocal remote = Instance.new(\"RemoteEvent\")\nremote.Name, remote.Parent = \"SlimeBatSwing\", ReplicatedStorage\nlocal lastSwing, stuns = {}, {}\nlocal tool = Instance.new(\"Tool\")\ntool.Name, tool.CanBeDropped = \"Slime Bat\", false\ntool.ToolTip = \"Knock back a rival and drop their baby. Bases are safe.\"\ntool.Grip = CFrame.new(0, -0.8, 0)\nlocal function part(name, size, offset, color)\n    local p = Instance.new(\"Part\")\n    p.Name, p.Size, p.CFrame, p.Color = name, size, CFrame.new(offset), color\n    p.Material, p.CanCollide, p.CanTouch, p.Massless = Enum.Material.SmoothPlastic, false, false, true\n    p.Parent = tool\n    return p\nend\nlocal handle = part(\"Handle\", Vector3.new(.38, 1.4, .38), Vector3.zero, Color3.fromRGB(62,69,89))\nlocal barrel = part(\"PaddedHead\", Vector3.new(1.1, 3, 1.1), Vector3.new(0, 2, 0), Color3.fromRGB(70,218,255))\nlocal cap = part(\"EndCap\", Vector3.new(1.15,.22,1.15), Vector3.new(0,3.55,0), Color3.fromRGB(166,255,49))\nfor _, p in ipairs({barrel, cap}) do\n    local weld = Instance.new(\"WeldConstraint\")\n    weld.Part0, weld.Part1, weld.Parent = handle, p, handle\nend\ntool.Parent = StarterPack\nlocal function getLiving(player)\n    local character = player.Character\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    local hum = character and character:FindFirstChildOfClass(\"Humanoid\")\n    if root and hum and hum.Health > 0 then return character, root, hum end\nend\nlocal function feedback(player, text)\n    remote:FireClient(player, \"Message\", text)\nend\nlocal function animate(bat)\n    local rest = CFrame.new(0, -.8, 0)\n    local forward = TweenService:Create(bat, TweenInfo.new(.10), {Grip = rest * CFrame.Angles(0, 0, math.rad(-95))})\n    forward:Play()\n    task.delay(.12, function()\n        if bat.Parent then TweenService:Create(bat, TweenInfo.new(.16), {Grip = rest}):Play() end\n    end)\nend\nlocal function knockback(player, root, humanoid, attackerRoot)\n    local now = workspace:GetServerTimeNow()\n    player:SetAttribute(\"BatProtectedUntil\", now + Rules.HitProtection)\n    player:SetAttribute(\"BatStunnedUntil\", now + Rules.StunDuration)\n    local record = {humanoid = humanoid, speed = humanoid.WalkSpeed, rotate = humanoid.AutoRotate}\n    stuns[player] = record\n    humanoid.WalkSpeed, humanoid.AutoRotate = 0, false\n    local delta = root.Position - attackerRoot.Position\n    local flat = Vector3.new(delta.X, 0, delta.Z)\n    local direction = flat.Magnitude > .01 and flat.Unit or attackerRoot.CFrame.LookVector\n    -- Server owns the short impact, so a client cannot suppress it.\n    local canOwn = root:CanSetNetworkOwnership()\n    if canOwn then root:SetNetworkOwner(nil) end\n    root:ApplyImpulse((direction * Rules.Knockback + Vector3.new(0,12,0)) * root.AssemblyMass)\n    local glow = Instance.new(\"Highlight\")\n    glow.Name, glow.Adornee = \"BatProtection\", player.Character\n    glow.FillColor, glow.OutlineColor = Color3.fromRGB(132,239,255), Color3.new(1,1,1)\n    glow.FillTransparency, glow.OutlineTransparency = .8, .25\n    glow.Parent = player.Character\n    Debris:AddItem(glow, Rules.HitProtection)\n    task.delay(Rules.StunDuration, function()\n        if stuns[player] ~= record then return end\n        stuns[player] = nil\n        if humanoid.Parent and humanoid.Health > 0 then\n            humanoid.WalkSpeed, humanoid.AutoRotate = record.speed, record.rotate\n            refreshMovement:Invoke(player)\n        end\n        if root.Parent and canOwn then root:SetNetworkOwnershipAuto() end\n    end)\nend\nlocal function clearLine(a, b, attacker, target)\n    local params = RaycastParams.new()\n    params.FilterType = Enum.RaycastFilterType.Exclude\n    local excluded = {attacker, target}\n    for _, p in ipairs(Players:GetPlayers()) do\n        if p.Character then table.insert(excluded, p.Character) end\n    end\n    local map = workspace:FindFirstChild(\"SlimeMap\")\n    if map then\n        if map:FindFirstChild(\"WildSlimes\") then table.insert(excluded, map.WildSlimes) end\n        if map:FindFirstChild(\"Guardians\") then table.insert(excluded, map.Guardians) end\n    end\n    params.FilterDescendantsInstances = excluded\n    return not workspace:Raycast(a, b - a, params)\nend\nlocal function swing(player)\n    local character, root = getLiving(player)\n    if not character then return end\n    local bat = character:FindFirstChild(tool.Name)\n    if not bat or not bat:IsA(\"Tool\") or not bat:FindFirstChild(\"PaddedHead\") then return end\n    local now = workspace:GetServerTimeNow()\n    if Rules.IsStunned(player) then return end\n    if now - (lastSwing[player] or -math.huge) < Rules.SwingCooldown then return end\n    -- Rate limit rejected attempts as well as accepted swings.\n    lastSwing[player] = now\n    if player:GetAttribute(\"CarryingSlime\") then feedback(player, \"Put down your baby before swinging.\"); return end\n    if Rules.IsSafe(character) then feedback(player, \"Bases and the collect zone are safe.\"); return end\n    animate(bat)\n    local nearest, distance\n    for _, other in ipairs(Players:GetPlayers()) do\n        if other ~= player then\n            local c, r, h = getLiving(other)\n            if c and not Rules.IsSafe(c) and (other:GetAttribute(\"BatProtectedUntil\") or 0) <= now then\n                local delta = r.Position - root.Position\n                local d = delta.Magnitude\n                -- A short forward arc, never a hit behind the attacker or through a wall.\n                if d <= Rules.Range and (d < .01 or root.CFrame.LookVector:Dot(delta.Unit) >= .15)\n                    and clearLine(root.Position, r.Position, character, c)\n                    and (not distance or d < distance) then\n                    nearest, distance = {player = other, root = r, humanoid = h}, d\n                end\n            end\n        end\n    end\n    if nearest then\n        -- Drop before stun, so capture restores the normal walking speed first.\n        nearest.player:SetAttribute(\"BatProtectedUntil\", now + Rules.HitProtection)\n        nearest.player:SetAttribute(\"BatStunnedUntil\", now + Rules.StunDuration)\n        local dropped = interrupt:Invoke(nearest.player)\n        knockback(nearest.player, nearest.root, nearest.humanoid, root)\n        feedback(player, dropped and \"Hit! Their baby is on the ground.\" or \"Hit!\")\n        feedback(nearest.player, dropped and \"Baby dropped! Equip your grabber to recover it.\" or \"Hit! You have two seconds of protection.\")\n    end\nend\nremote.OnServerEvent:Connect(function(player, action)\n    if action == \"Drop\" then\n        local character = getLiving(player)\n        if character and player:GetAttribute(\"CarryingSlime\") and not Rules.IsStunned(player) and not Rules.IsSafe(character) then\n            interrupt:Invoke(player)\n        end\n    elseif action == nil or action == \"Swing\" then\n        swing(player)\n    end\nend)\nlocal function setup(player)\n    local function characterAdded(character)\n        stuns[player] = nil\n        player:SetAttribute(\"BatStunnedUntil\", nil)\n        player:SetAttribute(\"BatProtectedUntil\", nil)\n        local backpack = player:WaitForChild(\"Backpack\")\n        if player.Character == character and not backpack:FindFirstChild(tool.Name) and not character:FindFirstChild(tool.Name) then\n            tool:Clone().Parent = backpack\n        end\n    end\n    player.CharacterAdded:Connect(characterAdded)\n    if player.Character then task.spawn(characterAdded, player.Character) end\nend\nPlayers.PlayerAdded:Connect(setup)\nPlayers.PlayerRemoving:Connect(function(player) lastSwing[player], stuns[player] = nil, nil end)\nfor _, player in ipairs(Players:GetPlayers()) do setup(player) end\nprint(\"Slime Bat ready: 0.9s swings, 2s protection, safe bases, shared dropped babies.\")\n" end
do local p=game:GetService("ServerScriptService"); local s=p:FindFirstChild("Inventory"); if not s then s=Instance.new("Script");s.Name="Inventory";s.Parent=p end;assert(s.ClassName=="Script");s.Source="-- Private session inventory, roaming pens, growth, and automatic server-paid income.\nlocal Players=game:GetService(\"Players\")\nlocal RS=game:GetService(\"ReplicatedStorage\")\nlocal Storage=game:GetService(\"ServerStorage\")\nlocal RunService=game:GetService(\"RunService\")\nlocal HttpService=game:GetService(\"HttpService\")\nlocal Income=require(script.Parent:WaitForChild(\"IncomeRules\"))\nlocal map=workspace:WaitForChild(\"SlimeMap\")\nlocal bases=map:WaitForChild(\"Bases\")\nlocal capture=script.Parent:WaitForChild(\"Capture\")\nlocal securedEvent=capture:WaitForChild(\"SlimeSecured\")\nlocal secured=Storage:WaitForChild(\"SecuredSlimes\")\nlocal remote=Instance.new(\"RemoteEvent\",RS);remote.Name=\"SlimeInventory\"\nlocal displays=Instance.new(\"Folder\",map);displays.Name=\"PlacedSlimes\"\nlocal GROW_SECONDS,CAPACITY,ACTION_INTERVAL=12,6,.15\nlocal states,owners,lastAction={}, {}, {}\nlocal random=Random.new()\nlocal function notice(p,message) if p.Parent then remote:FireClient(p,\"Message\",message) end end\nlocal function rate(state)\n    local total=0\n    for _,record in pairs(state.items) do if record.inPen then total+=Income.Rate(record.kind,record.weight) end end\n    return total\nend\nlocal function settle(player,state)\n    local now=os.clock()\n    state.cash+=(now-state.lastPaid)*rate(state)\n    state.lastPaid=now\n    local earned=rate(state)\n    player:SetAttribute(\"Cash\",math.floor(state.cash*100+.0001)/100)\n    player:SetAttribute(\"IncomePerSecond\",earned)\n    state.cashValue.Value=math.floor(state.cash)\nend\nlocal function snapshot(p)\n    local state=states[p];if not state then return end\n    local items={};local count=0\n    for id,r in pairs(state.items) do\n        if r.inPen then count+=1 end\n        table.insert(items,{id=id,kind=r.kind,rarity=r.rarity,weight=r.weight,color=r.source.PrimaryPart.Color,\n            inPen=r.inPen==true,progress=math.floor(r.progress*100+.0001)/100,rate=Income.Rate(r.kind,r.weight)})\n    end\n    table.sort(items,function(a,b)return a.id<b.id end)\n    remote:FireClient(p,\"Snapshot\",{items=items,selected=state.selected,base=state.base and state.base:GetAttribute(\"BaseIndex\"),\n        capacity=CAPACITY,placed=count,cash=state.cash,income=rate(state)})\nend\n-- Other server scripts can spend private cash without trusting a client balance.\nlocal spend=Instance.new(\"BindableFunction\")\nspend.Name=\"TrySpendCash\"\nspend.OnInvoke=function(p,amount)\n    local state=states[p]\n    if not state or type(amount)~=\"number\" or amount~=amount or amount<=0 or amount==math.huge then return false end\n    settle(p,state)\n    if state.cash<amount then return false end\n    state.cash-=amount -- No yielding between checking and subtracting.\n    settle(p,state);snapshot(p)\n    return true\nend\nspend.Parent=script\nlocal function showBaseName(base,p)\n    for _,label in ipairs(base:GetDescendants()) do\n        if label:IsA(\"TextLabel\") then label.Text=p and (p.DisplayName..\"'S PEN\") or (\"PEN 0\"..base:GetAttribute(\"BaseIndex\")) end\n    end\nend\nlocal function claim(p)\n    local state=states[p];if not state or state.base then return end\n    local sorted=bases:GetChildren()\n    table.sort(sorted,function(a,b)return a:GetAttribute(\"BaseIndex\")<b:GetAttribute(\"BaseIndex\") end)\n    for _,base in ipairs(sorted) do\n        if not owners[base] then\n            owners[base],state.base=p,base;base:SetAttribute(\"OwnerUserId\",p.UserId)\n            p:SetAttribute(\"BaseIndex\",base:GetAttribute(\"BaseIndex\"));showBaseName(base,p);snapshot(p);return\n        end\n    end\nend\nlocal function canUse(p,base)\n    local state=states[p];local c=p.Character\n    local root=c and c:FindFirstChild(\"HumanoidRootPart\");local hum=c and c:FindFirstChildOfClass(\"Humanoid\")\n    if not state or not base or state.base~=base or owners[base]~=p or not root or not hum or hum.Health<=0 then return false end\n    local grass=base.PenGrass;local position=grass.CFrame:PointToObjectSpace(root.Position)\n    return math.abs(position.X)<=grass.Size.X*.5+4 and math.abs(position.Z)<=grass.Size.Z*.5+4 and math.abs(position.Y)<=12\nend\nlocal function bounds(state,r)\n    local grass=state.base.PenGrass\n    return grass.Position,grass.Size.X*.5-r.radius,grass.Size.Z*.5-r.radius\nend\nlocal function target(state,r)\n    local center,hx,hz=bounds(state,r)\n    local best,bestDistance\n    for _=1,16 do\n        local point=Vector3.new(center.X+random:NextNumber(-hx,hx),0,center.Z+random:NextNumber(-hz,hz))\n        local distance=math.huge\n        for _,other in pairs(state.items) do\n            if other~=r and other.inPen and other.position then distance=math.min(distance,(point-other.position).Magnitude-other.radius-r.radius) end\n        end\n        if not bestDistance or distance>bestDistance then best,bestDistance=point,distance end\n        if distance>1 then return point end\n    end\n    return best\nend\nlocal function updateDisplay(state,r)\n    local scale=.65+(r.targetScale-.65)*r.progress\n    r.display:ScaleTo(scale)\n    local box,size=r.display:GetBoundingBox()\n    local offset=r.display:GetPivot().Position.Y-(box.Position.Y-size.Y*.5)\n    local grass=state.base.PenGrass\n    local bounce=math.abs(math.sin(r.phase))*(r.moving and .28 or .035)\n    r.display:PivotTo(CFrame.new(r.position.X,grass.Position.Y+grass.Size.Y*.5+.05+offset+bounce,r.position.Z)*r.rotation)\nend\nlocal function store(p,id)\n    local state=states[p];local r=state and state.items[id]\n    if not r or not r.inPen then return false end\n    if not canUse(p,state.base) then notice(p,\"Stand in your own pen to bring a slime back.\");return false end\n    settle(p,state);r.inPen=false\n    if r.display then r.display:Destroy();r.display=nil end\n    r.source:SetAttribute(\"GrowthProgress\",r.progress)\n    settle(p,state);snapshot(p);notice(p,\"Returned to inventory. Stored slimes do not earn cash.\")\n    return true\nend\nlocal function place(p,id)\n    local state=states[p];local r=state and state.items[id]\n    if not r or r.inPen then return false end\n    if not state.base then notice(p,\"Waiting for an available pen.\");return false end\n    if not canUse(p,state.base) then notice(p,\"Stand in your own pen to release a slime.\");return false end\n    local count=0;for _,other in pairs(state.items) do if other.inPen then count+=1 end end\n    if count>=CAPACITY then notice(p,\"Your pen is full (6 slimes). Return one to inventory first.\");return false end\n    settle(p,state)\n    local display=r.source:Clone()\n    for _,item in ipairs(display:GetDescendants()) do\n        if item:IsA(\"ProximityPrompt\") or item:IsA(\"Beam\") or item:IsA(\"WeldConstraint\") then item:Destroy()\n        elseif item:IsA(\"BasePart\") then item.Anchored,item.CanCollide,item.CanTouch=true,false,false end\n    end\n    display:SetAttribute(\"Weight\",nil);display:SetAttribute(\"GrowthProgress\",nil);display:SetAttribute(\"CarrierUserId\",nil)\n    display:SetAttribute(\"OwnerUserId\",p.UserId);display:SetAttribute(\"InventoryId\",id)\n    display.Name=r.kind..\"Pen_\"..string.sub(id,1,8)\n    r.targetScale=.8+r.weight^(1/3)*.55\n    local size=r.source:GetExtentsSize()\n    -- Reserve adult-sized margins so a growing slime cannot poke through fences.\n    r.radius=math.min(math.max(size.X,size.Z)*r.targetScale*.5+.8,11)\n    r.display,r.inPen=display,true;r.position=target(state,r);r.goal=target(state,r)\n    r.rotation=CFrame.identity;r.pauseUntil=0;r.phase=random:NextNumber(0,math.pi*2);r.blocked=0\n    display.Parent=displays\n    local prompt=Instance.new(\"ProximityPrompt\",display.PrimaryPart)\n    prompt.Name,prompt.ActionText,prompt.ObjectText=\"StoreSlime\",\"Return to inventory\",r.kind..\" Slime\"\n    prompt.MaxActivationDistance,prompt.HoldDuration,prompt.RequiresLineOfSight=12,0,false\n    prompt.Triggered:Connect(function(who)\n        if who==p and who.Character and (who.Character:GetPivot().Position-display:GetPivot().Position).Magnitude<=16 then store(who,id) end\n    end)\n    updateDisplay(state,r);settle(p,state);snapshot(p)\n    notice(p,\"Slime released! Cash is added automatically while it is in your pen.\")\n    return true\nend\nfor _,base in ipairs(bases:GetChildren()) do\n    -- Also migrate map geometry saved by previous versions.\n    local pads=base:FindFirstChild(\"CollectionSpots\");if pads then pads:Destroy() end\n    base:SetAttribute(\"PenCapacity\",CAPACITY)\n    local anchor=Instance.new(\"Part\")\n    anchor.Name=\"PenEntrance\";anchor.Size=Vector3.new(1,1,1)\n    anchor.Position=base:GetAttribute(\"EntrancePosition\")+Vector3.new(0,3,0)\n    anchor.Anchored,anchor.Transparency,anchor.CanCollide,anchor.CanTouch,anchor.CanQuery=true,1,false,false,false\n    anchor.Parent=base\n    local prompt=Instance.new(\"ProximityPrompt\",anchor)\n    prompt.Name,prompt.ActionText,prompt.ObjectText=\"PenPrompt\",\"Release selected slime\",\"Slime pen\"\n    prompt.MaxActivationDistance,prompt.HoldDuration,prompt.RequiresLineOfSight=12,0,false\n    prompt.Triggered:Connect(function(p)\n        local state=states[p]\n        if not state or state.base~=base then notice(p,\"This is another player's pen.\");return end\n        if os.clock()-(lastAction[p] or -math.huge)<ACTION_INTERVAL then return end\n        lastAction[p]=os.clock()\n        if state.selected then place(p,state.selected) else notice(p,\"Open Slimes [I] and select a baby first.\") end\n    end)\nend\nlocal function add(p,source)\n    local state=states[p];local folder=secured:FindFirstChild(tostring(p.UserId))\n    if not state or not folder or source.Parent~=folder or not source.PrimaryPart then return end\n    local id=source:GetAttribute(\"InventoryId\");if id and state.items[id] then return end\n    local weight=source:GetAttribute(\"Weight\")\n    if type(weight)~=\"number\" or weight~=weight or weight<=0 or weight==math.huge then return end\n    id=HttpService:GenerateGUID(false);source:SetAttribute(\"InventoryId\",id);source:SetAttribute(\"GrowthProgress\",0)\n    state.items[id]={source=source,weight=weight,kind=source:GetAttribute(\"SlimeType\"),rarity=source:GetAttribute(\"Rarity\"),progress=0}\n    state.selected=state.selected or id;snapshot(p)\nend\nlocal function setup(p)\n    if states[p] then return end\n    local stats=p:FindFirstChild(\"leaderstats\") or Instance.new(\"Folder\",p);stats.Name=\"leaderstats\"\n    local cash=Instance.new(\"IntValue\",stats);cash.Name=\"Cash\"\n    states[p]={items={},cash=0,lastPaid=os.clock(),cashValue=cash}\n    settle(p,states[p]);claim(p)\n    task.spawn(function()\n        local folder=secured:WaitForChild(tostring(p.UserId),30)\n        if folder and states[p] then for _,source in ipairs(folder:GetChildren()) do add(p,source) end end\n    end)\nend\nsecuredEvent.Event:Connect(add)\nPlayers.PlayerAdded:Connect(setup)\nfor _,p in ipairs(Players:GetPlayers()) do setup(p) end\nPlayers.PlayerRemoving:Connect(function(p)\n    local state=states[p];if not state then return end\n    for _,r in pairs(state.items) do if r.display then r.display:Destroy() end end\n    local base=state.base;states[p],lastAction[p]=nil,nil\n    if base then\n        owners[base]=nil;base:SetAttribute(\"OwnerUserId\",nil);showBaseName(base,nil)\n        for _,waiting in ipairs(Players:GetPlayers()) do if waiting~=p then claim(waiting) end end\n    end\nend)\nremote.OnServerEvent:Connect(function(p,action,id)\n    local state=states[p];if not state then return end\n    if os.clock()-(lastAction[p] or -math.huge)<ACTION_INTERVAL then return end\n    lastAction[p]=os.clock()\n    if action==\"Request\" then settle(p,state);snapshot(p);return end\n    if type(id)~=\"string\" or #id>64 or not state.items[id] then return end\n    if action==\"Select\" then state.selected=id;snapshot(p)\n    elseif action==\"Store\" then store(p,id)\n    elseif action==\"Place\" then place(p,id) end\nend)\nlocal elapsed,sendElapsed=0,0\nRunService.Heartbeat:Connect(function(dt)\n    elapsed+=dt;sendElapsed+=dt;if elapsed<.1 then return end\n    local step=elapsed;elapsed=0;local send=sendElapsed>=1;if send then sendElapsed=0 end\n    local now=os.clock()\n    for p,state in pairs(states) do\n        settle(p,state)\n        for _,r in pairs(state.items) do\n            if r.inPen then\n                r.progress=math.min(1,r.progress+step/GROW_SECONDS);r.source:SetAttribute(\"GrowthProgress\",r.progress)\n                local delta=r.goal-r.position;r.moving=false\n                if now>=r.pauseUntil then\n                    if delta.Magnitude<.5 then\n                        r.pauseUntil=now+random:NextNumber(.5,1.6);r.goal=target(state,r)\n                    else\n                        local candidate=r.position+delta.Unit*math.min(delta.Magnitude,2.6*math.min(step,.25))\n                        local clear=true\n                        for _,other in pairs(state.items) do\n                            if other~=r and other.inPen and other.position and (candidate-other.position).Magnitude<(r.radius+other.radius)*.8 then clear=false;break end\n                        end\n                        if clear then r.position=candidate;r.rotation=r.rotation:Lerp(CFrame.lookAt(Vector3.zero,-delta.Unit),.3);r.moving=true;r.blocked=0\n                        else r.blocked+=step;if r.blocked>1 then r.goal=target(state,r);r.blocked=0 end end\n                    end\n                end\n                local center,hx,hz=bounds(state,r)\n                r.position=Vector3.new(math.clamp(r.position.X,center.X-hx,center.X+hx),0,math.clamp(r.position.Z,center.Z-hz,center.Z+hz))\n                r.phase+=step*(r.moving and 7 or 2);updateDisplay(state,r)\n            end\n        end\n        if send then snapshot(p) end\n    end\nend)\nprint(\"Pens ready: roaming slimes, automatic income, no collection pads.\")\n" end
do local p=game:GetService("ServerScriptService"); local s=p:FindFirstChild("Upgrades"); if not s then s=Instance.new("Script");s.Name="Upgrades";s.Parent=p end;assert(s.ClassName=="Script");s.Source="-- ServerScriptService > Upgrades. Prices and balances never come from the client.\nlocal Players = game:GetService(\"Players\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal Rules = require(script.Parent:WaitForChild(\"UpgradeRules\"))\nlocal spend = script.Parent:WaitForChild(\"Inventory\"):WaitForChild(\"TrySpendCash\")\nlocal remote = Instance.new(\"RemoteEvent\")\nremote.Name, remote.Parent = \"SlimeUpgrades\", RS\nlocal levels, lastAction = {}, {}\nlocal function publish(player)\n    local state = levels[player]\n    player:SetAttribute(\"SpeedLevel\", state.Speed)\n    player:SetAttribute(\"GrabberLevel\", state.Grabber)\n    player:SetAttribute(\"GrabberPower\", Rules.Power(state.Grabber))\nend\nlocal function snapshot(player, message)\n    local state = levels[player]\n    if not state then return end\n    remote:FireClient(player, {\n        speedLevel = state.Speed, grabberLevel = state.Grabber, maxLevel = Rules.MaxLevel,\n        speedCost = Rules.Cost(\"Speed\", state.Speed), grabberCost = Rules.Cost(\"Grabber\", state.Grabber),\n        speed = Rules.Speed(state.Speed), power = Rules.Power(state.Grabber),\n        holdSeconds = Rules.HoldSeconds(state.Grabber), message = message,\n    })\nend\nlocal function setup(player)\n    if levels[player] then return end\n    levels[player] = {Speed = 0, Grabber = 0}\n    publish(player)\nend\nPlayers.PlayerAdded:Connect(setup)\nPlayers.PlayerRemoving:Connect(function(player) levels[player], lastAction[player] = nil, nil end)\nfor _, player in ipairs(Players:GetPlayers()) do setup(player) end\nremote.OnServerEvent:Connect(function(player, action, kind)\n    if not levels[player] then return end\n    local now = os.clock()\n    if now - (lastAction[player] or -math.huge) < 0.2 then return end\n    lastAction[player] = now\n    if action == \"Request\" then snapshot(player); return end\n    if action ~= \"Buy\" or (kind ~= \"Speed\" and kind ~= \"Grabber\") then return end\n    local state = levels[player]\n    local cost = Rules.Cost(kind, state[kind])\n    if not cost then snapshot(player, \"Maximum level reached for now.\"); return end\n    -- Inventory owns the private cash balance and subtracts the exact server price.\n    if not spend:Invoke(player, cost) then snapshot(player, \"Not enough cash. Release slimes into your pen to earn more.\"); return end\n    state[kind] = state[kind] + 1\n    publish(player)\n    snapshot(player, (kind == \"Speed\" and \"Speed\" or \"Grabber Power\") .. \" upgraded!\")\nend)\nprint(\"Upgrades ready: Speed and Grabber Power, five levels each, session-only.\")\n" end
do local p=game:GetService("ServerScriptService"); local s=p:FindFirstChild("CombatRules"); if not s then s=Instance.new("ModuleScript");s.Name="CombatRules";s.Parent=p end;assert(s.ClassName=="ModuleScript");s.Source="-- ModuleScript in ServerScriptService. Shared by capture and bat validation.\nlocal Rules = {\n    SwingCooldown = 0.9,\n    HitProtection = 2,\n    StunDuration = 0.55,\n    Range = 8,\n    Knockback = 34,\n    DropLifetime = 30,\n}\nlocal map = workspace:WaitForChild(\"SlimeMap\")\nlocal trigger = map:WaitForChild(\"CollectZone\"):WaitForChild(\"CollectionTrigger\")\nRules.SafeZ = trigger.Position.Z - trigger.Size.Z / 2\nfunction Rules.IsSafe(character)\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    return root ~= nil and root.Position.Z >= Rules.SafeZ\nend\nfunction Rules.IsStunned(player)\n    return (player:GetAttribute(\"BatStunnedUntil\") or 0) > workspace:GetServerTimeNow()\nend\nreturn Rules\n" end
do local p=game:GetService("ServerScriptService"); local s=p:FindFirstChild("IncomeRules"); if not s then s=Instance.new("ModuleScript");s.Name="IncomeRules";s.Parent=p end;assert(s.ClassName=="ModuleScript");s.Source="-- Server-only rates. Income is automatic for every placed slime, including growing babies.\nlocal baseRates = {Grass=1,Mud=2,Water=4,Honey=8,Crystal=16,Gold=32}\nlocal Rules = {}\nfunction Rules.Rate(kind, weight)\n    return math.floor((baseRates[kind] or 1) * weight^.6 * 100 + .5) / 100\nend\nreturn Rules\n" end
do local p=game:GetService("ServerScriptService"); local s=p:FindFirstChild("UpgradeRules"); if not s then s=Instance.new("ModuleScript");s.Name="UpgradeRules";s.Parent=p end;assert(s.ClassName=="ModuleScript");s.Source="-- Server-only balance settings. Rebirths can raise these limits in a later feature.\nlocal Rules = {MaxLevel = 5}\nfunction Rules.Cost(kind, level)\n    if (kind ~= \"Speed\" and kind ~= \"Grabber\") or level < 0 or level >= Rules.MaxLevel then return nil end\n    return (kind == \"Speed\" and 25 or 35) * 2 ^ level\nend\nfunction Rules.Speed(level) return 16 + 2 * level end\nfunction Rules.Power(level) return 10 + 2 * level end\nfunction Rules.HoldSeconds(level) return 2 / (1 + 0.15 * level) end\nfunction Rules.CarrySpeed(speedLevel, grabberLevel, weight, power)\n    local penalty = 0.35 / (1 + 0.15 * grabberLevel)\n    return math.max(6, Rules.Speed(speedLevel) * (1 - penalty * weight / math.max(1, power)))\nend\nreturn Rules\n" end
do local p=game:GetService("StarterPlayer").StarterPlayerScripts; local s=p:FindFirstChild("BatInput"); if not s then s=Instance.new("LocalScript");s.Name="BatInput";s.Parent=p end;assert(s.ClassName=="LocalScript");s.Source="-- StarterPlayerScripts: standard tool activation supports mouse, touch and controller.\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal ContextActionService = game:GetService(\"ContextActionService\")\nlocal player = Players.LocalPlayer\nlocal remote = ReplicatedStorage:WaitForChild(\"SlimeBatSwing\")\nlocal connected = setmetatable({}, {__mode = \"k\"})\nlocal function watch(tool)\n    if not tool:IsA(\"Tool\") or tool.Name ~= \"Slime Bat\" or connected[tool] then return end\n    connected[tool] = true\n    tool.Activated:Connect(function() remote:FireServer() end)\nend\nlocal function characterAdded(character)\n    character.ChildAdded:Connect(watch)\n    for _, tool in ipairs(character:GetChildren()) do watch(tool) end\nend\nplayer.CharacterAdded:Connect(characterAdded)\nif player.Character then characterAdded(player.Character) end\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name, gui.ResetOnSpawn = \"BatFeedback\", false\ngui.Parent = player:WaitForChild(\"PlayerGui\")\nlocal label = Instance.new(\"TextLabel\")\nlabel.AnchorPoint = Vector2.new(.5, 0)\nlabel.Position, label.Size = UDim2.new(.5,0,.18,0), UDim2.new(.8,0,0,48)\nlabel.BackgroundColor3, label.BackgroundTransparency = Color3.fromRGB(25,65,52), .1\nlabel.TextColor3, label.TextSize, label.Font = Color3.new(1,1,1), 20, Enum.Font.GothamBold\nlabel.TextWrapped, label.Visible, label.Parent = true, false, gui\nInstance.new(\"UICorner\", label).CornerRadius = UDim.new(0,10)\nlocal version = 0\nremote.OnClientEvent:Connect(function(kind, message)\n    if kind ~= \"Message\" then return end\n    version += 1\n    local current = version\n    label.Text, label.Visible, label.TextTransparency = message, true, 0\n    task.delay(2, function()\n        if current ~= version then return end\n        label.Visible = false\n    end)\nend)\n\n-- Carrying players can put a baby down before switching to their bat.\nlocal function updateDropAction()\n    ContextActionService:UnbindAction(\"DropBaby\")\n    if player:GetAttribute(\"CarryingSlime\") then\n        ContextActionService:BindAction(\"DropBaby\", function(_, state)\n            if state == Enum.UserInputState.Begin then remote:FireServer(\"Drop\") end\n            return Enum.ContextActionResult.Sink\n        end, true, Enum.KeyCode.Q, Enum.KeyCode.ButtonB)\n        ContextActionService:SetTitle(\"DropBaby\", \"Drop Baby\")\n        ContextActionService:SetPosition(\"DropBaby\", UDim2.new(1, -160, 1, -170))\n    end\nend\nplayer:GetAttributeChangedSignal(\"CarryingSlime\"):Connect(updateDropAction)\nupdateDropAction()\n" end
do local p=game:GetService("StarterPlayer").StarterPlayerScripts; local s=p:FindFirstChild("InventoryUI"); if not s then s=Instance.new("LocalScript");s.Name="InventoryUI";s.Parent=p end;assert(s.ClassName=="LocalScript");s.Source="local Players=game:GetService(\"Players\")\nlocal RS=game:GetService(\"ReplicatedStorage\")\nlocal UIS=game:GetService(\"UserInputService\")\nlocal player=Players.LocalPlayer\nlocal remote=RS:WaitForChild(\"SlimeInventory\")\nlocal state={items={}}\nlocal currentDetail\nlocal rarityColors={Common=Color3.fromRGB(182,191,180),Uncommon=Color3.fromRGB(107,226,69),Rare=Color3.fromRGB(57,187,255),Epic=Color3.fromRGB(190,116,255),Legendary=Color3.fromRGB(255,189,46)}\nlocal gui=Instance.new(\"ScreenGui\")\ngui.Name,gui.ResetOnSpawn=\"SlimeInventoryUI\",false\ngui.Parent=player:WaitForChild(\"PlayerGui\")\nlocal function rounded(o,r) local c=Instance.new(\"UICorner\",o);c.CornerRadius=UDim.new(0,r) end\nlocal function border(o,color,width) local s=Instance.new(\"UIStroke\",o);s.Color=color;s.Thickness=width;s.ApplyStrokeMode=Enum.ApplyStrokeMode.Border end\nlocal function label(parent,name,text,pos,size,fontSize)\n    local l=Instance.new(\"TextLabel\")\n    l.Name,l.Text,l.Position,l.Size=name,text,pos,size\n    l.BackgroundTransparency=1;l.Font=Enum.Font.GothamBold;l.TextSize=fontSize\n    l.TextColor3=Color3.fromRGB(246,255,233);l.TextWrapped=true;l.Parent=parent\n    return l\nend\nlocal function button(parent,name,text,pos,size,color)\n    local b=Instance.new(\"TextButton\")\n    b.Name,b.Text,b.Position,b.Size=name,text,pos,size\n    b.BackgroundColor3=color;b.Font=Enum.Font.GothamBlack;b.TextSize=17\n    b.TextColor3=Color3.new(1,1,1);b.TextStrokeTransparency=.25;b.Parent=parent\n    rounded(b,8);border(b,Color3.fromRGB(20,43,31),2)\n    return b\nend\nlocal open=button(gui,\"OpenInventory\",\"SLIMES  [I]\",UDim2.new(0,16,.48,0),UDim2.fromOffset(174,58),Color3.fromRGB(38,191,226))\nlocal panel=Instance.new(\"Frame\",gui)\npanel.Name=\"Panel\";panel.AnchorPoint=Vector2.new(.5,.5);panel.Position=UDim2.fromScale(.5,.48)\npanel.Size=UDim2.fromOffset(890,590);panel.BackgroundColor3=Color3.fromRGB(35,63,47);panel.Visible=false\nrounded(panel,14);border(panel,Color3.fromRGB(147,236,45),3)\nlocal max=Instance.new(\"UISizeConstraint\",panel);max.MaxSize=Vector2.new(890,590)\nlocal title=label(panel,\"Heading\",\"YOUR SLIMES\",UDim2.fromOffset(16,10),UDim2.new(1,-80,0,32),25)\ntitle.TextXAlignment=Enum.TextXAlignment.Left\nlocal close=button(panel,\"Close\",\"X\",UDim2.new(1,-49,0,11),UDim2.fromOffset(34,32),Color3.fromRGB(237,84,97))\nlocal instructions=label(panel,\"Instructions\",\"Select a slime and release it into your pen. Slimes wander and earn automatically. Hover or tap to inspect.\",UDim2.fromOffset(16,49),UDim2.new(1,-32,0,39),13)\nlocal list=Instance.new(\"ScrollingFrame\",panel)\nlist.Name=\"Items\";list.Position=UDim2.new(0,16,0,100);list.Size=UDim2.new(.61,-24,1,-116)\nlist.BackgroundColor3=Color3.fromRGB(26,48,37);list.BorderSizePixel=0;list.ScrollBarThickness=5\nlist.AutomaticCanvasSize=Enum.AutomaticSize.Y;list.CanvasSize=UDim2.new()\nrounded(list,8)\nlocal grid=Instance.new(\"UIGridLayout\",list)\ngrid.CellSize=UDim2.new(.5,-7,0,150);grid.CellPadding=UDim2.fromOffset(6,8)\nlocal padding=Instance.new(\"UIPadding\",list);padding.PaddingTop=UDim.new(0,6);padding.PaddingLeft=UDim.new(0,5)\nlocal info=Instance.new(\"Frame\",panel)\ninfo.Name=\"Details\";info.BackgroundTransparency=1;info.Position=UDim2.new(.61,2,0,99);info.Size=UDim2.new(.39,-18,1,-112)\nlocal base=label(info,\"Base\",\"ASSIGNING BASE...\",UDim2.new(),UDim2.new(1,0,0,30),18)\nlocal detail=label(info,\"WeightDetails\",\"Your secured babies appear here. Stored babies remain small until placed.\",UDim2.fromOffset(0,39),UDim2.new(1,0,0,111),15)\nlocal penCount=label(info,\"PenCount\",\"PEN 0 / 6\",UDim2.fromOffset(0,153),UDim2.new(1,0,0,28),20)\nlocal penIncome=label(info,\"PenIncome\",\"$0.00 / second\",UDim2.fromOffset(0,186),UDim2.new(1,0,0,28),18)\nlocal release=button(info,\"Release\",\"RELEASE INTO PEN\",UDim2.fromOffset(0,232),UDim2.new(1,0,0,48),Color3.fromRGB(89,187,54))\nlocal reclaim=button(info,\"Reclaim\",\"RETURN TO INVENTORY\",UDim2.fromOffset(0,293),UDim2.new(1,0,0,48),Color3.fromRGB(38,170,215))\nlabel(info,\"PenHint\",\"Stand inside your own pen to release or reclaim slimes. Cash is added automatically.\",UDim2.fromOffset(0,356),UDim2.new(1,0,0,80),14)\nrelease.Activated:Connect(function()\n    if state.selected then remote:FireServer(\"Place\",state.selected) end\nend)\nreclaim.Activated:Connect(function()\n    if state.selected then remote:FireServer(\"Store\",state.selected) end\nend)\nlocal cashHUD=label(gui,\"CashHUD\",\"$0\",UDim2.new(0,18,1,-146),UDim2.fromOffset(300,38),30)\ncashHUD.TextXAlignment=Enum.TextXAlignment.Left\ncashHUD.TextColor3=Color3.fromRGB(135,255,54);cashHUD.TextStrokeTransparency=0\nlocal rateHUD=label(gui,\"RateHUD\",\"+$0.00 / sec\",UDim2.new(0,18,1,-109),UDim2.fromOffset(300,28),17)\nrateHUD.TextXAlignment=Enum.TextXAlignment.Left;rateHUD.TextStrokeTransparency=0\nlocal function updateCash()\n    cashHUD.Text=string.format(\"$%.0f\",player:GetAttribute(\"Cash\") or 0)\n    rateHUD.Text=string.format(\"+$%.2f / sec\",player:GetAttribute(\"IncomePerSecond\") or 0)\nend\nplayer:GetAttributeChangedSignal(\"Cash\"):Connect(updateCash)\nplayer:GetAttributeChangedSignal(\"IncomePerSecond\"):Connect(updateCash)\nupdateCash()\nlocal message=label(gui,\"Notice\",\"\",UDim2.new(.15,0,.12,0),UDim2.new(.7,0,0,48),18)\nmessage.BackgroundColor3=Color3.fromRGB(35,63,47);message.BackgroundTransparency=.08;message.Visible=false;rounded(message,10)\nlocal function describe(item)\n    currentDetail=item.id\n    local status=item.inPen and (item.progress>=1 and \"Roaming in your pen\" or \"Growing in pen: \"..math.floor(item.progress*100)..\"%\")\n        or (item.progress>=1 and \"Stored \u00b7 Fully grown\" or (item.progress>0 and \"Stored \u00b7 Growth paused\" or \"Stored baby\"))\n    detail.Text=string.format(\"%s Slime\\n%s \u00b7 %.2f kg\\n%s\\n$%.2f / sec when in pen\",item.kind,item.rarity,item.weight,status,item.rate or 0)\nend\nlocal function preview(card,item)\n    local viewport=Instance.new(\"ViewportFrame\",card)\n    viewport.Position=UDim2.fromOffset(4,4);viewport.Size=UDim2.new(1,-8,0,87);viewport.BackgroundTransparency=1\n    viewport.Ambient=Color3.fromRGB(210,220,210);viewport.LightColor=Color3.new(1,1,1)\n    local model=Instance.new(\"WorldModel\",viewport)\n    local function ball(pos,size,color)\n        local p=Instance.new(\"Part\",model);p.Shape=Enum.PartType.Ball;p.Anchored=true\n        p.Position,p.Size,p.Color=pos,size,color;p.Material=Enum.Material.SmoothPlastic\n    end\n    ball(Vector3.new(0,0,0),Vector3.new(4,3,4),item.color)\n    for _,x in ipairs({-.65,.65}) do ball(Vector3.new(x,.55,-1.78),Vector3.new(.28,.4,.16),Color3.fromRGB(20,20,25)) end\n    ball(Vector3.new(0,.15,-1.98),Vector3.new(.4,.18,.16),Color3.fromRGB(20,20,25))\n    local camera=Instance.new(\"Camera\",viewport)\n    camera.CFrame=CFrame.lookAt(Vector3.new(0,2,-8),Vector3.zero);camera.FieldOfView=40;viewport.CurrentCamera=camera\nend\nlocal function render()\n    local oldScroll=list.CanvasPosition\n    for _,child in ipairs(list:GetChildren()) do if child:IsA(\"GuiObject\") then child:Destroy() end end\n    base.Text=state.base and (\"YOUR PEN 0\"..state.base) or \"WAITING FOR A PEN\"\n    if #state.items==0 then\n        local empty=label(list,\"Empty\",\"Capture a baby and bring it to the COLLECT ZONE.\",UDim2.new(),UDim2.fromOffset(200,150),17)\n        empty.LayoutOrder=0\n    end\n    local selectedInfo\n    for i,item in ipairs(state.items) do\n        local card=Instance.new(\"TextButton\",list)\n        card.Name=\"Item_\"..item.id;card.Size=UDim2.fromOffset(170,150);card.Text=\"\"\n        card.BackgroundColor3=Color3.fromRGB(63,89,66);card.LayoutOrder=i;rounded(card,9)\n        border(card,item.id==state.selected and Color3.fromRGB(179,255,60) or (rarityColors[item.rarity] or Color3.new(1,1,1)),item.id==state.selected and 3 or 2)\n        preview(card,item)\n        label(card,\"SlimeName\",item.kind,UDim2.fromOffset(4,91),UDim2.new(1,-8,0,20),16)\n        local status=item.inPen and (item.progress>=1 and \"IN PEN\" or \"GROWING \"..math.floor(item.progress*100)..\"%\") or \"IN INVENTORY\"\n        label(card,\"Status\",item.rarity..\" \u00b7 \"..status,UDim2.fromOffset(4,116),UDim2.new(1,-8,0,28),10)\n        card.MouseEnter:Connect(function() describe(item) end)\n        card.Activated:Connect(function() describe(item);remote:FireServer(\"Select\",item.id) end)\n        if item.id==currentDetail then selectedInfo=item end\n    end\n    if selectedInfo then describe(selectedInfo) end\n    penCount.Text=string.format(\"PEN %d / %d\",state.placed or 0,state.capacity or 6)\n    penIncome.Text=string.format(\"$%.2f / second\",state.income or 0)\n    local selected\n    for _,item in ipairs(state.items) do if item.id==state.selected then selected=item;break end end\n    release.Visible=selected~=nil and not selected.inPen\n    reclaim.Visible=selected~=nil and selected.inPen\n    list.CanvasPosition=oldScroll\nend\nlocal function toggle()\n    panel.Visible=not panel.Visible\n    if panel.Visible then render();remote:FireServer(\"Request\") end\nend\nopen.Activated:Connect(toggle)\nclose.Activated:Connect(function() panel.Visible=false end)\nUIS.InputBegan:Connect(function(input,processed)\n    if not processed and (input.KeyCode==Enum.KeyCode.I or input.KeyCode==Enum.KeyCode.ButtonY) then toggle() end\nend)\nlocal version=0\nremote.OnClientEvent:Connect(function(kind,data)\n    if kind==\"Snapshot\" then\n        state=data\n        open.Text=\"SLIMES (\"..#state.items..\")  [I]\"\n        if panel.Visible then render() end\n    elseif kind==\"Message\" then\n        version+=1;local this=version\n        message.Text,message.Visible=data,true\n        task.delay(3,function() if this==version then message.Visible=false end end)\n    end\nend)\nremote:FireServer(\"Request\")\n\nlocal uiScale=Instance.new(\"UIScale\",panel)\nlocal viewportConnection\nlocal function bindViewport()\n    if viewportConnection then viewportConnection:Disconnect() end\n    local camera=workspace.CurrentCamera\n    if not camera then return end\n    local function fit()\n        local size=camera.ViewportSize\n        uiScale.Scale=math.min(1,(size.X-24)/890,(size.Y*.78)/590)\n    end\n    viewportConnection=camera:GetPropertyChangedSignal(\"ViewportSize\"):Connect(fit)\n    fit()\nend\nworkspace:GetPropertyChangedSignal(\"CurrentCamera\"):Connect(bindViewport)\nbindViewport()\n" end
do local p=game:GetService("StarterPlayer").StarterPlayerScripts; local s=p:FindFirstChild("UpgradesUI"); if not s then s=Instance.new("LocalScript");s.Name="UpgradesUI";s.Parent=p end;assert(s.ClassName=="LocalScript");s.Source="-- StarterPlayerScripts > UpgradesUI. Buttons request purchases; the server decides.\nlocal Players = game:GetService(\"Players\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal CAS = game:GetService(\"ContextActionService\")\nlocal Prompts = game:GetService(\"ProximityPromptService\")\nlocal player = Players.LocalPlayer\nlocal remote = RS:WaitForChild(\"SlimeUpgrades\")\nlocal state, pending = nil, false\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name, gui.ResetOnSpawn, gui.DisplayOrder = \"SlimeUpgradesUI\", false, 5\ngui.Parent = player:WaitForChild(\"PlayerGui\")\nlocal function round(object)\n    local corner = Instance.new(\"UICorner\", object); corner.CornerRadius = UDim.new(0, 10)\nend\nlocal function label(parent, name, y, height, text, size)\n    local object = Instance.new(\"TextLabel\", parent)\n    object.Name, object.Text = name, text\n    object.Position, object.Size = UDim2.new(0, 16, 0, y), UDim2.new(1, -32, 0, height)\n    object.BackgroundTransparency, object.TextWrapped = 1, true\n    object.Font, object.TextSize, object.TextColor3 = Enum.Font.GothamBold, size, Color3.fromRGB(240, 255, 226)\n    return object\nend\nlocal function button(parent, name, y, text)\n    local object = Instance.new(\"TextButton\", parent)\n    object.Name, object.Text = name, text\n    object.Position, object.Size = UDim2.new(0, 16, 0, y), UDim2.new(1, -32, 0, 44)\n    object.BackgroundColor3, object.TextColor3 = Color3.fromRGB(101, 184, 63), Color3.new(1, 1, 1)\n    object.Font, object.TextSize = Enum.Font.GothamBold, 17\n    round(object)\n    return object\nend\nlocal open = button(gui, \"OpenUpgrades\", 0, \"UPGRADES [U]\")\nopen.Position, open.Size = UDim2.new(0, 16, 0.48, -58), UDim2.fromOffset(174, 50)\nlocal panel = Instance.new(\"Frame\", gui)\npanel.Name, panel.Visible, panel.AnchorPoint = \"Panel\", false, Vector2.new(0.5, 0.5)\npanel.Position, panel.Size = UDim2.fromScale(0.5, 0.4), UDim2.new(0.9, 0, 0, 400)\npanel.BackgroundColor3 = Color3.fromRGB(35, 63, 47); round(panel)\nlocal bounds = Instance.new(\"UISizeConstraint\", panel)\nbounds.MaxSize = Vector2.new(510, 400)\nlabel(panel, \"Heading\", 12, 32, \"UPGRADES\", 24)\nlocal cash = label(panel, \"Cash\", 48, 28, \"Cash: $0\", 19)\nlocal speed = label(panel, \"Speed\", 82, 42, \"Loading...\", 17)\nlocal speedBuy = button(panel, \"BuySpeed\", 128, \"Loading...\")\nlocal power = label(panel, \"Grabber\", 184, 48, \"Loading...\", 16)\nlocal powerBuy = button(panel, \"BuyGrabber\", 237, \"Loading...\")\nlocal notice = label(panel, \"Notice\", 287, 48, \"Upgrades last this session. Saving comes later.\", 14)\nlocal close = button(panel, \"Close\", 345, \"CLOSE\")\nlocal function update()\n    local balance = player:GetAttribute(\"Cash\") or 0\n    cash.Text = string.format(\"Cash: $%.2f\", balance)\n    if not state then return end\n    speed.Text = string.format(\"SPEED  %d / %d\\nRun speed: %d\", state.speedLevel, state.maxLevel, state.speed)\n    power.Text = string.format(\"GRABBER POWER  %d / %d\\nPower: %d  \u00b7  Pull: %.2fs  \u00b7  Less carrying slowdown\", state.grabberLevel, state.maxLevel, state.power, state.holdSeconds)\n    for _, item in ipairs({{speedBuy, state.speedCost}, {powerBuy, state.grabberCost}}) do\n        local object, cost = item[1], item[2]\n        object.Text = cost and (\"BUY \u2014 $\" .. cost) or \"MAX LEVEL\"\n        object.Active = cost ~= nil and not pending\n        object.AutoButtonColor = object.Active\n        object.BackgroundColor3 = cost and balance >= cost and Color3.fromRGB(101, 184, 63) or Color3.fromRGB(91, 105, 82)\n    end\nend\nlocal function toggle()\n    panel.Visible = not panel.Visible\n    if panel.Visible then\n        local inventory = player.PlayerGui:FindFirstChild(\"SlimeInventoryUI\")\n        if inventory then inventory.Panel.Visible = false end\n        remote:FireServer(\"Request\")\n    end\nend\nopen.Activated:Connect(toggle)\nclose.Activated:Connect(function() panel.Visible = false end)\nCAS:BindAction(\"OpenSlimeUpgrades\", function(_, input)\n    if input == Enum.UserInputState.Begin then toggle() end\n    return Enum.ContextActionResult.Sink\nend, false, Enum.KeyCode.U)\nlocal function buy(kind)\n    if not state or pending or not (kind == \"Speed\" and state.speedCost or kind == \"Grabber\" and state.grabberCost) then return end\n    pending = true; update()\n    remote:FireServer(\"Buy\", kind)\n    task.delay(0.35, function() pending = false; update() end)\nend\nspeedBuy.Activated:Connect(function() buy(\"Speed\") end)\npowerBuy.Activated:Connect(function() buy(\"Grabber\") end)\nremote.OnClientEvent:Connect(function(data)\n    state, pending = data, false\n    if data.message then notice.Text = data.message end\n    update()\nend)\nplayer:GetAttributeChangedSignal(\"Cash\"):Connect(update)\n-- Only the local hold bar changes. Capture still measures the hold on the server.\nlocal visible, holding = {}, {}\nlocal function updatePrompt(prompt)\n    if not holding[prompt] and prompt.Name == \"CapturePrompt\" and prompt.ActionText == \"Pull with grabber\" then\n        prompt.HoldDuration = 2 / (1 + 0.15 * (player:GetAttribute(\"GrabberLevel\") or 0))\n    end\nend\nPrompts.PromptShown:Connect(function(prompt) visible[prompt] = true; updatePrompt(prompt) end)\nPrompts.PromptHidden:Connect(function(prompt) visible[prompt], holding[prompt] = nil, nil end)\nPrompts.PromptButtonHoldBegan:Connect(function(prompt) holding[prompt] = true end)\nPrompts.PromptButtonHoldEnded:Connect(function(prompt) holding[prompt] = nil; updatePrompt(prompt) end)\nplayer:GetAttributeChangedSignal(\"GrabberLevel\"):Connect(function()\n    for prompt in pairs(visible) do updatePrompt(prompt) end\nend)\nupdate(); remote:FireServer(\"Request\")\n" end
print("Speed and Grabber Power upgrades installed.")